import {SignIn,SignUp,useAuth,useUser,UserButton} from '@clerk/react';
import {Router,Route,Switch,Link,useLocation} from 'wouter';
import {ArrowLeft,ArrowRight,BookOpen,CalendarDays,Check,ClipboardList,Copy,ExternalLink,FileText,Home,Plus,RefreshCw,Users,X} from 'lucide-react';
import {edu,eduBlob,fileBase64,EduError,type EduAccess,type Course,type CourseDetail,type Announcement,type Material,type Assignment,type Submission} from './api';
