type Kind='announcement'|'material'|'assignment';
type Editor={kind:Kind;item?:Announcement|Material|Assignment};
const entity:Record<Kind,string>={announcement:'announcement',material:'material',assignment:'assignment'};
const collection:Record<Kind,string>={announcement:'announcements',material:'materials',assignment:'assignments'};
const FILE_TYPES:Record<string,string>={'application/pdf':'.pdf','text/plain':'.txt','image/png':'.png','image/jpeg':'.jpg','application/vnd.openxmlformats-officedocument.wordprocessingml.document':'.docx','application/vnd.openxmlformats-officedocument.presentationml.presentation':'.pptx'};
const FILE_ACCEPT=Object.keys(FILE_TYPES).join(',')+','+Object.values(FILE_TYPES).join(',');
function dateTime(value?:string|null){if(!value)return 'No deadline';const d=new Date(value);return Number.isNaN(d.getTime())?'No deadline':d.toLocaleString(undefined,{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'});}
function dateOnly(value:string){const d=new Date(value);return Number.isNaN(d.getTime())?'':d.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});}
function toLocalDate(value?:string|null){if(!value)return '';const d=new Date(value);if(Number.isNaN(d.getTime()))return '';const local=new Date(d.getTime()-d.getTimezoneOffset()*60000);return local.toISOString().slice(0,16);}
function shortStudentId(id:string,knownIds:string[]){
  if(id.length<=16)return id;
  for(let n=6;n<id.length;n+=2){
    const shortened=`${id.slice(0,n)}…${id.slice(-Math.max(4,Math.floor(n/2)))}`;
    if(knownIds.filter(other=>other!==id&&`${other.slice(0,n)}…${other.slice(-Math.max(4,Math.floor(n/2)))}`===shortened).length===0)return shortened;
  }
  return id;
}
function StudentIdentity({name,id,knownIds}:{name?:string|null;id?:string;knownIds:string[]}){
  const [copyError,setCopyError]=useState(false);
  const short=id?shortStudentId(id,knownIds):null;
  return <div className="student-identity"><strong data-testid={`text-student-identity-${id||'unavailable'}`}>{name?.trim()|| (short?`Student · ${short}`:'Student ID unavailable')}</strong>{id&&<div className="small-muted student-id" title={`Full student ID: ${id}`}><span>ID {short}</span><button type="button" className="copy-id" title={`Copy full student ID: ${id}`} aria-label={`Copy full student ID ${id}`} data-testid={`button-copy-student-id-${id}`} onClick={()=>{void navigator.clipboard.writeText(id).then(()=>setCopyError(false)).catch(()=>setCopyError(true))}}><Copy size={12}/> Copy ID</button>{copyError&&<span role="alert">Could not copy; select the ID from the tooltip.</span>}</div>}</div>;
}
function ErrorBox({error,retry}:{error:string;retry?:()=>void}){return <div className="notice" role="alert" data-testid="status-error">{error}{retry&&<button type="button" onClick={retry} data-testid="button-retry">Try again</button>}</div>;}
function Loading(){return <div aria-label="Loading classroom" role="status"><div className="skeleton"/><div className="skeleton" style={{height:84}}/><div className="skeleton" style={{height:84}}/></div>;}
function Button({children,onClick,variant='',type='button',disabled=false,testId,ariaLabel}:{children:ReactNode;onClick?:()=>void;variant?:string;type?:'button'|'submit';disabled?:boolean;testId:string;ariaLabel?:string}){return <button className={`button ${variant}`} type={type} onClick={onClick} disabled={disabled} data-testid={testId} aria-label={ariaLabel}>{children}</button>;}
function Modal({title,kicker,children,onClose}:{title:string;kicker:string;children:ReactNode;onClose:()=>void}){useEffect(()=>{const fn=(e:KeyboardEvent)=>{if(e.key==='Escape')onClose()};document.addEventListener('keydown',fn);return()=>document.removeEventListener('keydown',fn)},[onClose]);return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className="modal" role="dialog" aria-modal="true" aria-label={title}><div className="modal-head"><div><p className="eyebrow">{kicker}</p><h2>{title}</h2></div><Button variant="subtle small" onClick={onClose} testId="button-close-dialog" ariaLabel="Close dialog"><X size={17}/></Button></div>{children}</div></div>;}

function Workspace(){
  const {getToken,isLoaded,isSignedIn}=useAuth();
  const {user}=useUser();
  const [location,setLocation]=useLocation();
  const [courses,setCourses]=useState<Course[]>([]);
  const [access,setAccess]=useState<EduAccess|null>(null);
  const [accessError,setAccessError]=useState('');
  const [loading,setLoading]=useState(true);
  const [error,setError]=useState('');
  const [unauthorized,setUnauthorized]=useState(false);
  const [dialog,setDialog]=useState<'create'|'join'|null>(null);
  const [busy,setBusy]=useState(false);
  const [formError,setFormError]=useState('');
  const generation=useRef(0);
  const locationRef=useRef(location);
  locationRef.current=location;
  const lastGrantRef=useRef(false);
  const active=useRef(true);
  useEffect(()=>{active.current=true;return()=>{active.current=false;generation.current++}},[]);
   const revoke=useCallback(()=>{generation.current++;lastGrantRef.current=false;setAccess({canCreateCourse:false,canJoinLicensedCourse:false,needsCredentials:true,canManageSchool:false});setCourses([]);setDialog(null);setFormError('');setError('');setLoading(false);setLocation('/')},[setLocation]);
   const api=useCallback(async <T,>(path:string,method='GET',body?:unknown):Promise<T>=>{try{return await edu<T>(path,getToken,method,body)}catch(e){if(active.current&&e instanceof EduError&&e.status===403&&(e.code==='edu_license_required'||e.code==='edu_credentials_required'))revoke();throw e}},[getToken,revoke]);
  const load=useCallback(async(silent:boolean,grant:EduAccess)=>{if(!silent)setLoading(true);setError('');const requestGeneration=generation.current;try{const result=await api<{courses:Course[]}>('/courses');if(requestGeneration===generation.current){const visible=grant.canCreateCourse?result.courses:result.courses.filter(c=>c.role==='student');setCourses(visible);const selected=locationRef.current.match(/^\/courses\/([^/]+)/)?.[1];if(selected&&!visible.some(c=>c.id===selected))setLocation('/');setUnauthorized(false)}}catch(e){if(requestGeneration===generation.current){setCourses([]);if(e instanceof EduError&&e.status===401)setUnauthorized(true);else if(!(e instanceof EduError&&e.code==='edu_license_required'))setError(e instanceof Error?e.message:'Could not load classrooms.')}}finally{if(!silent&&requestGeneration===generation.current)setLoading(false)}},[api,setLocation]);
   const checkAccess=useCallback(async()=>{const requestGeneration=++generation.current;setLoading(true);setAccess(null);setCourses([]);setError('');setAccessError('');setDialog(null);try{const result=await edu<EduAccess>('/access',getToken);if(requestGeneration!==generation.current)return;if(lastGrantRef.current&&!result.canCreateCourse)setLocation('/');lastGrantRef.current=result.canCreateCourse;setAccess(result);setUnauthorized(false);if(result.needsCredentials){setLoading(false);return}await load(false,result)}catch(e){if(requestGeneration!==generation.current)return;if(e instanceof EduError&&e.status===401)setUnauthorized(true);else if(e instanceof EduError&&e.code==='edu_license_required')revoke();else setAccessError(e instanceof Error?e.message:'Could not check EDU access.');setLoading(false)}},[getToken,load,revoke,setLocation]);
  useEffect(()=>{if(isLoaded&&isSignedIn)void checkAccess();else if(isLoaded){generation.current++;lastGrantRef.current=false;setCourses([]);setAccess(null);setLoading(false)}},[isLoaded,isSignedIn,checkAccess]);
  useEffect(()=>{if(!isLoaded||!isSignedIn)return;const onFocus=()=>{if(document.visibilityState==='visible')void checkAccess()};document.addEventListener('visibilitychange',onFocus);return()=>document.removeEventListener('visibilitychange',onFocus)},[isLoaded,isSignedIn,checkAccess]);
  useEffect(()=>{if(!isLoaded||!isSignedIn)return;const timer=window.setInterval(()=>{if(document.visibilityState==='visible')void checkAccess()},60000);return()=>window.clearInterval(timer)},[isLoaded,isSignedIn,checkAccess]);
  async function submitEntry(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!dialog||!access)return;const data=new FormData(event.currentTarget);setBusy(true);setFormError('');try{
    if(dialog==='create'&&!access?.canCreateCourse){setDialog(null);return}
    const result=dialog==='create'?await api<{course:Course}>('/courses','POST',{name:String(data.get('name')||'').trim(),subject:String(data.get('subject')||'').trim(),term:String(data.get('term')||'').trim()}):await api<{course:Course}>('/join','POST',{inviteCode:String(data.get('inviteCode')||'').trim()});
    setDialog(null);await load(true,access);setLocation(`/courses/${result.course.id}`);
  }catch(e){if(!(e instanceof EduError&&e.code==='edu_license_required'))setFormError(e instanceof Error?e.message:'Could not save.')}finally{setBusy(false)}}
  if(!isLoaded||loading&&isSignedIn)return <div className="main"><div className="wrap"><Loading/></div></div>;
  if(!isSignedIn||unauthorized)return <AuthPage unauthorized={unauthorized}/>;
  if(accessError||!access)return <div className="main"><div className="access-retry"><p className="eyebrow">EDU / Access check</p><h1>We couldn’t check your access.</h1><p>Your classroom information is hidden until we can verify your EDU access. Please try again.</p><ErrorBox error={accessError||'EDU access is unavailable.'} retry={()=>void checkAccess()}/></div></div>;
   if(access.needsCredentials)return <Activation api={api} verified={()=>void checkAccess()}/>;
  const licensed=access.canCreateCourse;
  const visibleCourses=licensed?courses:courses.filter(c=>c.role==='student');
  const selectedId=location.match(/^\/courses\/([^/]+)/)?.[1];
  return <div className="shell">
    <aside className="rail"><Link href="/" className="brand" data-testid="link-classscribe-edu"><span className="mark" aria-hidden="true">C</span><span><strong>ClassScribe</strong><small>EDU / WORKSPACE</small></span></Link>
      <p className="rail-label">Workspace</p><Link href="/" className={`navitem ${location==='/'?'active':''}`} data-testid="link-classrooms"><Home/> Classrooms</Link>{access.canManageSchool&&<Link href="/school" className={`navitem ${location==='/school'?'active':''}`} data-testid="link-school-instructors"><Users/> School instructors</Link>}
      <div className="rail-label" style={{marginTop:28}}>{licensed?'Your courses':'Joined classrooms'}</div><nav className="rail-courses" aria-label="Your courses">{visibleCourses.map(c=><Link href={`/courses/${c.id}`} className={`navitem ${selectedId===c.id?'active':''}`} key={c.id} data-testid={`link-course-${c.id}`}><span className="course-dot"/><span style={{overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{c.name}</span></Link>)}</nav>
      <div className="rail-bottom"><div className="identity">{user?.primaryEmailAddress?.emailAddress||user?.fullName||'Signed in'}<div style={{marginTop:8}}><UserButton/></div></div><a className="backlink" href="/" data-testid="link-private-library">Back to private study library <ArrowRight size={13} style={{verticalAlign:'middle'}}/></a></div>
    </aside>
    <main className="main"><div className="wrap"><div className="topline"><span className="eyebrow">ClassScribe <span style={{color:'#9aada2'}}>/</span> EDU</span><div className="top-actions">{access.canJoinLicensedCourse&&<Button variant="subtle small" onClick={()=>setDialog('join')} testId="button-join-class">Join with code</Button>}{licensed&&<Button variant="primary small" onClick={()=>setDialog('create')} testId="button-create-course"><Plus/> New course</Button>}</div></div>
      <Switch><Route path="/">{licensed?<div className="hero"><div><p className="eyebrow">Your teaching space</p><h1>A clearer place for every class.</h1><p>Coursework, conversation, and feedback in one focused workspace.</p></div><Button onClick={()=>setDialog('create')} testId="button-create-first-course">Create a course <ArrowRight/></Button></div>:<LicenseRequired onJoin={access.canJoinLicensedCourse?()=>setDialog('join'):undefined}/>}<div className="section-head"><div><h2>{licensed?'Classrooms':'Your joined classrooms'}</h2><p>{licensed?'Courses you teach and classes you’ve joined.':'Classes you have joined with an instructor’s code.'}</p></div><Button variant="small" onClick={()=>void checkAccess()} testId="button-refresh-courses"><RefreshCw/> Refresh</Button></div>{error&&<ErrorBox error={error} retry={()=>void checkAccess()}/>}
        {visibleCourses.length?<div className="course-grid">{visibleCourses.map(c=><Link className="card course-card" href={`/courses/${c.id}`} key={c.id} data-testid={`card-course-${c.id}`}><div><div className="eyebrow">{c.subject||'Classroom'} · {c.term||'Current course'}</div><h3>{c.name}</h3></div><footer><span className={`pill ${c.role==='student'?'student':''}`}>{c.role==='instructor'?'Teaching':'Enrolled'}</span><span>{typeof c.memberCount==='number'?`${c.memberCount} members`:'Open classroom'} &nbsp; →</span></footer></Link>)}</div>:!error&&<div className="placeholder"><BookOpen size={25}/><h3>{licensed?'Your classrooms start here.':'No joined classrooms yet.'}</h3><p>{licensed?'Create a course to invite students, or join a classroom with the code your instructor shared.':'If your instructor shared a code for a licensed course, use it to join here.'}</p><div className="top-actions">{licensed&&<Button variant="primary" onClick={()=>setDialog('create')} testId="button-empty-create">Create course</Button>}{access.canJoinLicensedCourse&&<Button onClick={()=>setDialog('join')} testId="button-empty-join">Join with code</Button>}</div></div>}</Route>
      <Route path="/school">{access.canManageSchool?<SchoolPanel api={api}/>:<div className="placeholder"><h2>School administration unavailable</h2><Link href="/" className="button">Back to classrooms</Link></div>}</Route><Route path="/courses/:id">{({id})=>licensed||visibleCourses.some(c=>c.id===id)?<CoursePage key={id} id={id} api={api} onCourseChange={()=>load(true,access)}/>:<div className="placeholder"><h2>Classroom unavailable</h2><p>Teaching access requires an approved EDU license. Joined student classrooms remain available from your classroom list.</p><Link href="/" className="button" data-testid="link-back-classrooms">Back to classrooms</Link></div>}</Route><Route><div className="placeholder"><h2>Classroom not found</h2><Link href="/" className="button" data-testid="link-back-classrooms">Back to classrooms</Link></div></Route></Switch>
    </div></main>
     <nav className="mobilebar" aria-label="Mobile navigation"><Link href="/" data-testid="link-mobile-classrooms"><Home/>Classrooms</Link>{access.canManageSchool&&<Link href="/school" data-testid="link-mobile-school"><Users/>School</Link>}<a href="/" data-testid="link-mobile-library"><BookOpen/>Library</a>{access.canJoinLicensedCourse&&<button type="button" onClick={()=>setDialog('join')} data-testid="button-mobile-join" className="navitem" style={{width:'auto',display:'grid',placeItems:'center',fontSize:11,padding:0}}><Users/>Join</button>}</nav>
    {dialog&&<Modal title={dialog==='create'?'Create a course':'Join a classroom'} kicker={dialog==='create'?'For instructors':'For students'} onClose={()=>{setDialog(null);setFormError('')}}><form onSubmit={submitEntry} className="fields">{formError&&<ErrorBox error={formError}/>}
      {dialog==='create'?<><label>Course name<input name="name" required maxLength={140} placeholder="Introduction to Environmental Science" data-testid="input-course-name" autoFocus/></label><label>Subject <small>Optional</small><input name="subject" maxLength={100} placeholder="Environmental Science" data-testid="input-course-subject"/></label><label>Term <small>Optional</small><input name="term" maxLength={100} placeholder="Fall 2026" data-testid="input-course-term"/></label></>:<label>Class code<input name="inviteCode" required autoCapitalize="characters" autoComplete="off" placeholder="Enter the code from your instructor" data-testid="input-class-code" autoFocus/></label>}
      <div className="form-actions"><Button onClick={()=>setDialog(null)} testId="button-cancel-entry">Cancel</Button><Button type="submit" variant="primary" disabled={busy} testId="button-submit-entry">{busy?'Working…':dialog==='create'?'Create course':'Join classroom'}</Button></div></form></Modal>}
  </div>;
}
function Activation({api,verified}:{api:<T>(path:string,method?:string,body?:unknown)=>Promise<T>;verified:()=>void}){
   const {user}=useUser();
  const [pin,setPin]=useState(''),[license,setLicense]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');
  async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setError('');const entered=pin;setPin('');try{await api('/activate','POST',{licenseNumber:license.trim().toUpperCase(),clientPin:entered});verified()}catch(err){if(err instanceof EduError&&err.code==='edu_credentials_locked')setError('Verification is temporarily locked after too many attempts. Wait at least 15 minutes before trying again.');else if(err instanceof EduError&&err.code==='edu_credentials_invalid')setError('That license number and client PIN do not match an active EDU license. Check both with your instructor or license administrator.');else setError(err instanceof Error?err.message:'Could not verify credentials.')}finally{setBusy(false)}}
   return <div className="main"><div className="activation"><span className="mark">C</span><p className="eyebrow" style={{marginTop:22}}>ClassScribe / EDU access</p><h1>Open your classroom.</h1><p>Enter the license number and client PIN provided by your EDU license administrator. Instructors and students verify this pair for each Clerk session. The PIN is never saved in this browser.</p>{user?.id&&<div className="card" style={{marginBottom:16}}><strong>Your Clerk user ID</strong><p style={{overflowWrap:'anywhere'}} data-testid="text-own-clerk-user-id">{user.id}</p><p className="small-muted">If you are an instructor, give this ID to your school administrator for approval. An ID alone cannot grant access.</p></div>}{error&&<ErrorBox error={error}/>}<form className="fields" onSubmit={submit}><label>License number<input value={license} onChange={e=>setLicense(e.target.value)} required pattern="EDU-[A-Fa-f0-9]{24}" placeholder="EDU-…" autoComplete="off" spellCheck={false}/></label><label>Client PIN<input type="password" value={pin} onChange={e=>setPin(e.target.value)} required pattern="[0-9]{8,12}" inputMode="numeric" autoComplete="off" placeholder="8–12 digits"/></label><button className="button primary" disabled={busy}>{busy?'Verifying…':'Verify EDU access'}</button></form><p className="feature-note">A signed EDU agreement must first be verified by an operator. A designated school administrator can then approve instructors under that agreement; entering credentials alone never grants teaching access.</p><div style={{marginTop:20}}><UserButton/></div></div></div>;
}

function LicenseRequired({onJoin}:{onJoin?:()=>void}){return <><section className="license-hero" data-testid="edu-license-required"><div><p className="eyebrow">Teaching access / Approval required</p><h1>Ready to teach? Let’s get you approved.</h1><p>Creating and managing a ClassScribe EDU course requires a signed EDU agreement, manual approval, and the assigned license number and client PIN for each Clerk session. Your account is signed in, but teaching access is not active.</p><div className="license-actions"><a className="button primary" href="/" data-testid="link-edu-help">Open ClassScribe to ask Help <ArrowRight/></a>{onJoin&&<Button onClick={onJoin} testId="button-license-join">Join with a class code</Button>}</div></div><div className="license-note"><span>Good to know</span><p><strong>Free, Student, and Pro plans do not unlock teaching access.</strong> There is no self-checkout or in-app agreement acceptance for EDU. Ask Help about licensing and the approval process.</p></div></section><div className="license-steps"><div className="license-step"><p className="eyebrow">01 / Teaching</p><h3>Start with an EDU agreement</h3><p>Contact Help in ClassScribe to ask what EDU includes and how to request an agreement. Teaching access starts after the signed agreement is manually approved and the assigned license number and client PIN are verified for the session.</p></div><div className="license-step"><p className="eyebrow">02 / Learning</p><h3>Joining a class?</h3><p>Students need the assigned license number and client PIN after Clerk sign-in for each session, plus the instructor’s class code to join. Students do not need their own teaching grant.</p></div></div></>}

function AuthPage({unauthorized=false}:{unauthorized?:boolean}){
  const [path,setPath]=useLocation();
  const {isLoaded,isSignedIn}=useAuth();
  useEffect(()=>{if(isLoaded&&isSignedIn&&!unauthorized)setPath('/')},[isLoaded,isSignedIn,unauthorized,setPath]);
  const signingUp=path.startsWith('/sign-up');
  return <div className="auth"><div className="auth-art"><Link href="/" className="brand" style={{padding:0,color:'inherit'}} data-testid="link-auth-home"><span className="mark" style={{background:'#f2cf4f',color:'#164b3a'}}>C</span><span><strong>ClassScribe</strong><small style={{color:'#d1e6d7'}}>EDU / WORKSPACE</small></span></Link><div><div className="eyebrow" style={{color:'#c9e9d7',marginBottom:18}}>A classroom with room to think</div><h1>Teach clearly.<br/>Keep learning personal.</h1><p>Course materials, assignments, grades, discussion, lecture recordings, and source libraries live together. Students keep their own study libraries private.</p><div className="auth-license"><strong>Instructors need a signed EDU agreement and manual approval.</strong> After Clerk sign-in, instructors and students each enter the assigned license number and client PIN for every session. Students also need the instructor’s class code to join a course. Signing in or choosing a Free, Student, or Pro plan does not unlock teaching access.</div></div><a href="/" style={{color:'#e5f3e8'}} data-testid="link-auth-library">Return to ClassScribe ↗</a></div><div className="auth-main"><div><div className="eyebrow" style={{color:'var(--green)',marginBottom:12}}>Classroom access</div><h2>{signingUp?'Create your account':'Welcome back'}</h2><p>{unauthorized?'Your session needs to be renewed. Sign out below, then sign back in.':signingUp?'An account protects classroom grades. Creating one does not grant teaching access.':'Sign in, then verify the assigned license number and client PIN to see your EDU classrooms.'}</p>{unauthorized&&isSignedIn?<SessionReset/>:signingUp?<SignUp routing="hash" signInUrl="/instructor/sign-in" forceRedirectUrl="/instructor/"/>:<SignIn routing="hash" signUpUrl="/instructor/sign-up" forceRedirectUrl="/instructor/"/>}<div className="auth-help">Interested in teaching? <a href="/" data-testid="link-auth-help">Open ClassScribe and ask Help</a> what EDU includes and how to request a license. There is no self-checkout or in-app agreement acceptance.</div></div></div></div>;
}
function SessionReset(){const {signOut}=useAuth();return <Button variant="primary" onClick={()=>void signOut({redirectUrl:'/instructor/sign-in'})} testId="button-renew-session">Sign out to renew session</Button>;}

function CoursePage({id,api,onCourseChange}:{id:string;api:<T>(path:string,method?:string,body?:unknown)=>Promise<T>;onCourseChange:()=>Promise<void>}){
   const {getToken}=useAuth();
  const [detail,setDetail]=useState<CourseDetail|null>(null);
  const [loading,setLoading]=useState(true);
  const [error,setError]=useState('');
  const [actionError,setActionError]=useState('');
   const [tab,setTab]=useState<'overview'|'announcements'|'materials'|'assignments'|'people'|'gradebook'|'discussion'|'groups'|'lectures'|'sources'>('overview');
  const [editor,setEditor]=useState<Editor|null>(null);
  const [invite,setInvite]=useState<string|null>(null);
  const [inviteBusy,setInviteBusy]=useState(false);
  const [inviteError,setInviteError]=useState('');
  const [review,setReview]=useState<{assignment:Assignment;studentId?:string}|null>(null);
  const [gradebookRevision,setGradebookRevision]=useState(0);
  const [submit,setSubmit]=useState<Assignment|null>(null);
  const [busy,setBusy]=useState(false);
  const [formError,setFormError]=useState('');
   const [fileMode,setFileMode]=useState(false);
   const [contentFile,setContentFile]=useState<File|null>(null);
   const [preview,setPreview]=useState<{title:string;url:string;mimeType:string}|null>(null);
  const detailLoadGeneration=useRef(0);
  const load=useCallback(async(silent=false)=>{const generation=++detailLoadGeneration.current;if(!silent)setLoading(true);setError('');try{const response=await api<CourseDetail>(`/courses/${encodeURIComponent(id)}`);if(generation===detailLoadGeneration.current)setDetail(response)}catch(e){if(generation===detailLoadGeneration.current)setError(e instanceof Error?e.message:'Could not load this classroom.')}finally{if(generation===detailLoadGeneration.current)setLoading(false)}},[api,id]);
  useEffect(()=>{void load()},[load]);
  const base=`/courses/${encodeURIComponent(id)}`;
  async function mutate(path:string,method:string,body?:unknown){setBusy(true);setFormError('');try{await api(path,method,body);await Promise.all([load(true),onCourseChange()]);setEditor(null);setSubmit(null);setActionError('');return true}catch(e){setFormError(e instanceof Error?e.message:'Could not save changes.');return false}finally{setBusy(false)}}
   function chooseEditor(next:Editor){setContentFile(null);setFileMode(false);setFormError('');setEditor(next)}
   async function downloadFile(path:string,filename:string){setActionError('');try{const blob=await eduBlob(path,getToken);const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();window.setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(e){setActionError(e instanceof Error?e.message:'Could not download the file.')}}
   async function previewFile(path:string,title:string,mimeType:string){setActionError('');try{const blob=await eduBlob(path,getToken);setPreview(previous=>{if(previous)URL.revokeObjectURL(previous.url);return {title,url:URL.createObjectURL(blob),mimeType}})}catch(e){setActionError(e instanceof Error?e.message:'Could not open the file.')}}
   function closePreview(){setPreview(previous=>{if(previous)URL.revokeObjectURL(previous.url);return null})}
   async function uploadFile(path:string,file:File,extra:Record<string,unknown>={}){if(!file.size||file.size>10*1024*1024||!Object.keys(FILE_TYPES).includes(file.type)||!file.name.toLowerCase().endsWith(FILE_TYPES[file.type]))throw new Error('Choose a PDF, TXT, PNG, JPG, DOCX, or PPTX file no larger than 10 MB.');return api(path,'POST',{...extra,filename:file.name,mimeType:file.type,data:await fileBase64(file)})}
   async function saveEditor(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!editor)return;const f=new FormData(e.currentTarget);let body:Record<string,unknown>={title:String(f.get('title')||'').trim()};if(editor.kind==='announcement')body.body=String(f.get('body')||'').trim();if(editor.kind==='material'){if(!fileMode&&!((editor.item as Material|undefined)?.filename))body.url=String(f.get('url')||'').trim();body.description=String(f.get('description')||'').trim()}if(editor.kind==='assignment'){body.instructions=String(f.get('instructions')||'').trim();body.points=Number(f.get('points'));body.dueAt=f.get('dueAt')?new Date(String(f.get('dueAt'))).toISOString():null}
     const path=`${base}/${collection[editor.kind]}${editor.item?`/${encodeURIComponent(editor.item.id)}`:''}`;
     if(editor.kind==='material'&&fileMode&&!editor.item){setBusy(true);setFormError('');try{if(!contentFile)throw new Error('Choose a file first.');await uploadFile(`${base}/materials/uploads`,contentFile,body);await load(true);setEditor(null);setContentFile(null)}catch(err){setFormError(err instanceof Error?err.message:'Could not upload the material.')}finally{setBusy(false)}return}
     if(editor.kind==='assignment'&&contentFile&&!editor.item){setBusy(true);setFormError('');try{if(contentFile.size>10*1024*1024||!FILE_TYPES[contentFile.type]||!contentFile.name.toLowerCase().endsWith(FILE_TYPES[contentFile.type]))throw new Error('Choose a PDF, TXT, PNG, JPG, DOCX, or PPTX file no larger than 10 MB.');const result=await api<{assignment:Assignment}>(path,'POST',body);try{await uploadFile(`${base}/assignments/${result.assignment.id}/attachment`,contentFile)}catch(err){await load(true);setEditor(null);setActionError(`Assignment published, but its attachment was not saved: ${err instanceof Error?err.message:'Upload failed.'} Add it from the assignment card.`);return}await load(true);setEditor(null);setContentFile(null)}catch(err){setFormError(err instanceof Error?err.message:'Could not save the assignment.')}finally{setBusy(false)}return}
     await mutate(path,editor.item?'PATCH':'POST',body);}
   async function attachExisting(item:Assignment,file:File){setActionError('');try{await uploadFile(`${base}/assignments/${item.id}/attachment`,file);await load(true)}catch(e){setActionError(e instanceof Error?e.message:'Could not attach the file.')}}
   async function detachExisting(item:Assignment){if(!window.confirm(`Remove “${item.filename}” from this assignment? The file will be deleted.`))return;setActionError('');try{await api(`${base}/assignments/${item.id}/attachment`,'DELETE');await load(true)}catch(e){setActionError(e instanceof Error?e.message:'Could not remove the attachment.')}}
   async function remove(kind:Kind,item:{id:string;title:string;filename?:string|null}){if(!window.confirm(`Delete “${item.title}”? ${item.filename?'Its uploaded file will also be permanently removed. ':'This cannot be undone.'}`))return;setActionError('');try{await api(`${base}/${collection[kind]}/${encodeURIComponent(item.id)}`,'DELETE');await load(true)}catch(e){setActionError(e instanceof Error?e.message:'Could not delete item.')}}
  async function getInvite(){setInviteBusy(true);setActionError('');setInviteError('');try{const result=await api<{inviteCode:string}>(`${base}/invite`,'POST');setInvite(result.inviteCode)}catch(e){setActionError(e instanceof Error?e.message:'Could not create a class code.')}finally{setInviteBusy(false)}}
  async function rotateInvite(){if(!window.confirm('Rotate this class code? The old code and any links using it will stop working immediately. Students already enrolled stay in the class.'))return;setInviteBusy(true);setInviteError('');try{const result=await api<{inviteCode:string}>(`${base}/invite/rotate`,'POST');setInvite(result.inviteCode)}catch(e){setInviteError(e instanceof Error?e.message:'Could not rotate the class code. The displayed code has not been changed.')}finally{setInviteBusy(false)}}
  if(loading)return <Loading/>;
  if(error||!detail)return <div><Link href="/" className="button small" data-testid="link-error-back"><ArrowLeft/> Classrooms</Link><div style={{marginTop:20}}><ErrorBox error={error||'Classroom unavailable.'} retry={()=>void load()}/></div></div>;
  const owner=detail.role==='instructor';
  const {course,announcements,materials,assignments}=detail;
   const rosterIds=(detail.roster||[]).map(person=>person.userId||person.studentId||person.id).filter((value):value is string=>Boolean(value));
  const showTab=tab==='overview'?'announcements':tab;
  return <><Link href="/" className="button subtle small" data-testid="link-back-courses"><ArrowLeft/> All classrooms</Link>
    <div className="heading" style={{marginTop:24}}><div><p className="eyebrow">{course.subject||'Course'} {course.term?`/ ${course.term}`:''}</p><h1 data-testid="text-course-title">{course.name}</h1><p>{owner?'Your course workspace. What you publish is visible to enrolled students.':'Class updates, learning materials, and work assigned to you.'}</p></div><div className="top-actions"><Button variant="small" onClick={()=>void load()} testId="button-refresh-course"><RefreshCw/> Refresh</Button>{owner&&<Button variant="primary" onClick={()=>void getInvite()} disabled={inviteBusy} testId="button-invite-students"><Users/> {inviteBusy?'Preparing…':'Invite students'}</Button>}</div></div>
    {actionError&&<ErrorBox error={actionError}/>}
     <div className="tabs" role="tablist" aria-label="Classroom sections">{(['overview','announcements','materials','assignments','gradebook','discussion','groups','lectures','sources','people'] as const).filter(t=>owner||t!=='people').map(t=><button role="tab" aria-selected={tab===t} key={t} className={`tab ${tab===t?'active':''}`} onClick={()=>setTab(t)} data-testid={`tab-${t}`}>{t==='people'?'People':t[0].toUpperCase()+t.slice(1)}</button>)}</div>
     {tab==='gradebook'&&<GradebookPanel base={base} api={api} owner={owner} roster={detail.roster||[]} assignments={assignments} revision={gradebookRevision} review={(assignment,studentId)=>setReview({assignment,studentId})}/>}
     {tab==='discussion'&&<DiscussionPanel base={base} api={api} owner={owner} roster={detail.roster||[]} assignments={assignments} review={assignment=>setReview({assignment})}/>}
     {tab==='groups'&&<GroupsPanel base={base} api={api} owner={owner} roster={detail.roster||[]} assignments={assignments} review={assignment=>setReview({assignment})}/>}
     {tab==='lectures'&&<LecturesPanel base={base} api={api} owner={owner} roster={detail.roster||[]} assignments={assignments} review={assignment=>setReview({assignment})}/>}
     {tab==='sources'&&<SourcesPanel base={base} api={api} owner={owner} roster={detail.roster||[]} assignments={assignments} review={assignment=>setReview({assignment})}/>}
    {tab==='overview'?<div className="overview"><div className="stack"><div className="section-head" style={{marginTop:0}}><h2>Latest announcements</h2>{owner&&<Button variant="small" onClick={()=>setEditor({kind:'announcement'})} testId="button-new-announcement"><Plus/> Post update</Button>}</div>{announcements.length?announcements.slice(0,3).map(a=><AnnouncementCard key={a.id} item={a} owner={owner} edit={()=>setEditor({kind:'announcement',item:a})} remove={()=>void remove('announcement',a)}/>):<Empty label="No announcements yet" hint={owner?'Post an update to give everyone the same context.':'Your instructor has not posted an update.'}/>}
       <div className="section-head"><h2>Assignments</h2><Button variant="small" onClick={()=>setTab('assignments')} testId="button-view-assignments">View all <ArrowRight/></Button></div>{assignments.length?assignments.slice(0,3).map(a=><AssignmentCard key={a.id} item={a} owner={owner} edit={()=>chooseEditor({kind:'assignment',item:a})} remove={()=>void remove('assignment',a)} review={()=>setReview({assignment:a})} submit={()=>setSubmit(a)} download={()=>void downloadFile(`${base}/assignments/${a.id}/file`,a.filename||'attachment')} view={()=>void previewFile(`${base}/assignments/${a.id}/file`,a.filename||'attachment',a.mimeType||'')} attach={file=>void attachExisting(a,file)} detach={()=>void detachExisting(a)}/>):<Empty label="Nothing assigned yet" hint={owner?'Create an assignment with a due date and points.':'Assignments will appear here when your instructor publishes them.'}/>}</div><div className="detail-side"><div className="card"><p className="eyebrow">At a glance</p><div className="side-stat">{assignments.length}</div><p className="small-muted">assignments published</p><div className="side-stat">{materials.length}</div><p className="small-muted">materials available</p></div><div className="card"><p className="eyebrow">Course access</p><p style={{marginTop:12,fontWeight:700}}>{owner?'You teach this course':'You are enrolled'}</p><p className="small-muted" style={{marginTop:7}}>{owner?'Invite students with a class code.':'Your submissions and feedback are visible to you and your instructor.'}</p>{owner&&<Button variant="small" onClick={()=>void getInvite()} testId="button-overview-invite" ><Copy/> Get class code</Button>}</div></div></div>:null}
    {showTab==='announcements'&&tab!=='overview'&&<Section title="Announcements" count={announcements.length} owner={owner} add={()=>setEditor({kind:'announcement'})} addLabel="Post announcement" test="button-add-announcement">{announcements.length?announcements.map(a=><AnnouncementCard key={a.id} item={a} owner={owner} edit={()=>setEditor({kind:'announcement',item:a})} remove={()=>void remove('announcement',a)}/>):<Empty label="A quiet classroom, for now." hint={owner?'Share a note with everyone enrolled in this course.':'Your instructor has not posted an announcement.'}/>}</Section>}
     {tab==='materials'&&<Section title="Course materials" count={materials.length} owner={owner} add={()=>chooseEditor({kind:'material'})} addLabel="Add material" test="button-add-material">{materials.length?materials.map(m=><div className="feed-item" key={m.id} data-testid={`card-material-${m.id}`}><div className="feed-top"><div>{m.filename?<strong className="link-title">{m.title}</strong>:<a href={m.url} target="_blank" rel="noopener noreferrer" className="link-title" data-testid={`link-material-${m.id}`}>{m.title} <ExternalLink size={15} style={{verticalAlign:'middle'}}/></a>}<p>Added {dateOnly(m.createdAt)}</p></div>{owner&&<Actions edit={()=>chooseEditor({kind:'material',item:m})} remove={()=>void remove('material',m)} id={m.id}/>}</div>{m.description&&<p className="description">{m.description}</p>}{m.filename?<div className="top-actions" style={{marginTop:10}}>{m.mimeType&&canPreview(m.mimeType)&&<Button variant="small" onClick={()=>void previewFile(`${base}/materials/${m.id}/file`,m.filename!,m.mimeType!)} testId={`button-view-material-${m.id}`}>View</Button>}<Button variant="small" onClick={()=>void downloadFile(`${base}/materials/${m.id}/file`,m.filename!)} testId={`link-material-${m.id}`}>Download {m.filename}</Button><span className="small-muted">{((m.sizeBytes||0)/1024/1024).toFixed(2)} MB</span></div>:<p className="small-muted" style={{marginTop:10,overflowWrap:'anywhere'}}>{m.url}</p>}</div>):<Empty label="No materials yet" hint={owner?'Add a reading, slide deck, PDF, or reference link.':'Course files and links will appear here when your instructor adds them.'}/>}</Section>}
     {tab==='assignments'&&<Section title="Assignments" count={assignments.length} owner={owner} add={()=>chooseEditor({kind:'assignment'})} addLabel="New assignment" test="button-add-assignment">{assignments.length?assignments.map(a=><AssignmentCard key={a.id} item={a} owner={owner} edit={()=>chooseEditor({kind:'assignment',item:a})} remove={()=>void remove('assignment',a)} review={()=>setReview({assignment:a})} submit={()=>setSubmit(a)} download={()=>void downloadFile(`${base}/assignments/${a.id}/file`,a.filename||'attachment')} view={()=>void previewFile(`${base}/assignments/${a.id}/file`,a.filename||'attachment',a.mimeType||'')} attach={file=>void attachExisting(a,file)} detach={()=>void detachExisting(a)}/>):<Empty label="No assignments yet" hint={owner?'Publish the first task for your students.':'Your instructor has not published assignments.'}/>}</Section>}
     {tab==='people'&&owner&&<div className="stack"><div className="section-head" style={{marginTop:0}}><div><h2>Class roster</h2><p>Students enrolled in this course.</p></div><Button variant="primary small" onClick={()=>void getInvite()} testId="button-roster-invite"><Plus/> Invite</Button></div><div className="card">{detail.roster?.length?detail.roster.map((person,index)=>{const studentId=person.userId||person.studentId||person.id;return <div className="roster-row" key={studentId||index} data-testid={`row-student-${studentId||index}`}><div className="initials">{(person.name?.trim()||studentId||'?').charAt(0).toUpperCase()}</div><div><StudentIdentity name={person.name} id={studentId} knownIds={rosterIds}/>{person.email&&<p className="small-muted">{person.email}</p>}</div><span className="pill student" style={{marginLeft:'auto'}}>{person.role||'Student'}</span></div>}):<Empty label="No students on the roster yet" hint="Share your class code so students can enroll with their own account."/>}</div></div>}
    {invite!==null&&<Modal title="Invite your students" kicker="Class code" onClose={()=>{if(!inviteBusy)setInvite(null)}}><p>Students sign in to ClassScribe EDU and choose “Join with code”. Share this code only with your class.</p><div className="code-block" data-testid="text-invite-code">{invite}</div>{inviteError&&<ErrorBox error={inviteError}/>}<p className="small-muted">Need to replace a shared code? Rotating it immediately invalidates the old code and any links using it. Enrolled students remain in the class.</p><div className="form-actions"><Button variant="danger" onClick={()=>void rotateInvite()} disabled={inviteBusy} testId="button-rotate-code">{inviteBusy?'Rotating…':'Rotate code'}</Button><Button onClick={()=>setInvite(null)} disabled={inviteBusy} testId="button-invite-done">Done</Button><Button variant="primary" disabled={inviteBusy} onClick={()=>{void navigator.clipboard.writeText(invite).catch(()=>setInviteError('Could not copy. Select the code above instead.'))}} testId="button-copy-code"><Copy/> Copy code</Button></div></Modal>}
     {preview&&<Modal title={preview.title} kicker="Course file preview" onClose={closePreview}>{preview.mimeType.startsWith('image/')?<img src={preview.url} alt={preview.title} style={{display:'block',maxWidth:'100%',maxHeight:'70vh',margin:'auto'}}/>:<iframe title={preview.title} src={preview.url} style={{width:'100%',height:'65vh',border:0}}/>}</Modal>}
    {editor&&<Modal title={`${editor.item?'Edit':'New'} ${entity[editor.kind]}`} kicker="Course content" onClose={()=>{setEditor(null);setFormError('')}}><form className="fields" onSubmit={saveEditor}>{formError&&<ErrorBox error={formError}/>}<label>Title<input name="title" required maxLength={180} defaultValue={editor.item?.title||''} data-testid="input-content-title" autoFocus/></label>
      {editor.kind==='announcement'&&<label>Message<textarea name="body" required defaultValue={(editor.item as Announcement|undefined)?.body||''} data-testid="input-announcement-body"/></label>}
       {editor.kind==='material'&&<>{!editor.item&&<div className="top-actions"><Button variant={!fileMode?'primary small':'small'} onClick={()=>{setFileMode(false);setContentFile(null)}} testId="button-material-link">Link</Button><Button variant={fileMode?'primary small':'small'} onClick={()=>setFileMode(true)} testId="button-material-file">Upload file</Button></div>}{(editor.item as Material|undefined)?.filename?<p className="small-muted">File: {(editor.item as Material).filename}. Delete this material to remove its file.</p>:fileMode&&!editor.item?<label>Course file<input type="file" accept={FILE_ACCEPT} required onChange={e=>setContentFile(e.target.files?.[0]||null)} data-testid="input-material-file"/></label>:<label>URL<input type="url" name="url" required placeholder="https://…" defaultValue={(editor.item as Material|undefined)?.url||''} data-testid="input-material-url"/></label>}<label>Description <small>Optional</small><textarea name="description" defaultValue={(editor.item as Material|undefined)?.description||''} data-testid="input-material-description"/></label></>}
       {editor.kind==='assignment'&&<><label>Instructions<textarea name="instructions" required defaultValue={(editor.item as Assignment|undefined)?.instructions||''} data-testid="input-assignment-instructions"/></label><label>Deadline <small>Optional</small><input type="datetime-local" name="dueAt" defaultValue={toLocalDate((editor.item as Assignment|undefined)?.dueAt)} data-testid="input-assignment-deadline"/></label><label>Points<input type="number" name="points" min="0" step="1" required defaultValue={(editor.item as Assignment|undefined)?.points??100} data-testid="input-assignment-points"/></label>{!editor.item&&<label>Attachment <small>Optional · PDF, TXT, PNG, JPG, DOCX, PPTX · 10 MB max</small><input type="file" accept={FILE_ACCEPT} onChange={e=>setContentFile(e.target.files?.[0]||null)} data-testid="input-assignment-file"/></label>}</>}
       {editor.kind==='material'&&fileMode&&!editor.item&&<p className="small-muted">PDF, TXT, PNG, JPG, DOCX, or PPTX · 10 MB max. Only enrolled students in this classroom can download it.</p>}
      <div className="form-actions"><Button onClick={()=>setEditor(null)} testId="button-cancel-content">Cancel</Button><Button type="submit" variant="primary" disabled={busy} testId="button-save-content">{busy?'Saving…':editor.item?'Save changes':'Publish'}</Button></div></form></Modal>}
    {submit&&<Modal title={submit.mySubmission?'Your submission':'Submit your work'} kicker={submit.title} onClose={()=>setSubmit(null)}><SubmissionEditor key={submit.id} assignment={submit} base={base} api={api} cancel={()=>setSubmit(null)} saved={async (submission,cleanupPending)=>{
      // Apply the acknowledged mutation immediately and reject older in-flight reads.
      // Keep this dialog busy until the fresh course read finishes.
      ++detailLoadGeneration.current;
      setDetail(current=>current?{...current,assignments:current.assignments.map(a=>a.id===submit.id?{...a,mySubmission:submission??undefined}:a)}:current);
      await load(true);
      setSubmit(null);
      if(cleanupPending)setActionError('Your submission change was saved. File deletion is queued and will retry automatically.');
    }}/></Modal>}
    {review&&<ReviewModal key={`${review.assignment.id}:${review.studentId||''}`} assignment={review.assignment} focusStudentId={review.studentId} base={base} api={api} close={()=>setReview(null)} refresh={async()=>{await load(true);setGradebookRevision(n=>n+1)}} rosterIds={rosterIds}/>}
  </>;
}
function Empty({label,hint}:{label:string;hint:string}){return <div className="placeholder"><FileText size={22}/><h3>{label}</h3><p>{hint}</p></div>;}
function Section({title,count,owner,add,addLabel,test,children}:{title:string;count:number;owner:boolean;add:()=>void;addLabel:string;test:string;children:ReactNode}){return <div className="stack"><div className="section-head" style={{marginTop:0}}><div><h2>{title}</h2><p>{count} {count===1?'item':'items'}</p></div>{owner&&<Button variant="primary small" onClick={add} testId={test}><Plus/> {addLabel}</Button>}</div>{children}</div>;}
function Actions({edit,remove,id}:{edit:()=>void;remove:()=>void;id:string}){return <div className="feed-actions"><Button variant="small" onClick={edit} testId={`button-edit-${id}`}>Edit</Button><Button variant="small danger" onClick={remove} testId={`button-delete-${id}`}>Delete</Button></div>;}
function AnnouncementCard({item,owner,edit,remove}:{item:Announcement;owner:boolean;edit:()=>void;remove:()=>void}){return <article className="feed-item" data-testid={`card-announcement-${item.id}`}><div className="feed-top"><div><h3>{item.title}</h3><p>Posted {dateOnly(item.createdAt)}</p></div>{owner&&<Actions edit={edit} remove={remove} id={item.id}/>}</div><div className="body">{item.body}</div></article>;}
function canPreview(mimeType:string){return ['application/pdf','text/plain','image/png','image/jpeg'].includes(mimeType)}
function AssignmentCard({item,owner,edit,remove,review,submit,download,view,attach,detach}:{item:Assignment;owner:boolean;edit:()=>void;remove:()=>void;review:()=>void;submit:()=>void;download:()=>void;view:()=>void;attach:(file:File)=>void;detach:()=>void}){return <article className="feed-item" data-testid={`card-assignment-${item.id}`}><div className="feed-top"><div><h3>{item.title}</h3><div className="assignment-meta"><span><CalendarDays size={13}/> Due {dateTime(item.dueAt)}</span><span>{item.points} points</span></div></div>{owner&&<Actions edit={edit} remove={remove} id={item.id}/>}</div><div className="body">{item.instructions}</div>{item.filename?<div className="top-actions" style={{marginTop:12}}>{item.mimeType&&canPreview(item.mimeType)&&<Button variant="small" onClick={view} testId={`button-view-assignment-${item.id}`}>View file</Button>}<Button variant="small" onClick={download} testId={`button-download-assignment-${item.id}`}>Download {item.filename}</Button>{owner&&<Button variant="small danger" onClick={detach} testId={`button-remove-attachment-${item.id}`}>Remove attachment</Button>}</div>:owner&&<label style={{display:'block',marginTop:12}}>Add optional attachment · PDF, TXT, PNG, JPG, DOCX, PPTX · 10 MB max<input type="file" accept={FILE_ACCEPT} onChange={e=>{const file=e.target.files?.[0];if(file)attach(file);e.target.value=''}} data-testid={`input-attachment-${item.id}`}/></label>}{owner?<div style={{marginTop:18}}><Button variant="small" onClick={review} testId={`button-review-${item.id}`}><ClipboardList/> Review submissions</Button></div>:<>{item.mySubmission&&<div className="submission"><div className="feed-top"><strong>Your submission</strong><span className="small-muted">{dateTime(item.mySubmission.submittedAt)}</span></div><div className="body">{item.mySubmission.text}</div>{item.mySubmission.score!==null&&item.mySubmission.score!==undefined?<p style={{marginTop:13}}><span className="score">{item.mySubmission.score} / {item.points}</span>{item.mySubmission.feedback&&<span style={{display:'block',marginTop:6,whiteSpace:'pre-wrap'}}>Feedback: {item.mySubmission.feedback}</span>}</p>:<p className="small-muted" style={{marginTop:12}}>Awaiting feedback</p>}</div>}<div style={{marginTop:18}}><Button variant="small" onClick={submit} testId={`button-submit-assignment-${item.id}`}>{item.mySubmission?'Update response':'Write a response'} <ArrowRight/></Button></div></>}</article>;}
function ReviewModal({assignment,focusStudentId,base,api,close,refresh,rosterIds}:{assignment:Assignment;focusStudentId?:string;base:string;api:<T>(path:string,method?:string,body?:unknown)=>Promise<T>;close:()=>void;refresh:()=>Promise<void>;rosterIds:string[]}){
  const [submissions,setSubmissions]=useState<Submission[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [saving,setSaving]=useState<string|null>(null);
  const [showAll,setShowAll]=useState(false);
  const load=useCallback(async()=>{setLoading(true);setError('');try{const result=await api<{submissions:Submission[]}>(`${base}/assignments/${encodeURIComponent(assignment.id)}/submissions`);setSubmissions(result.submissions)}catch(e){setError(e instanceof Error?e.message:'Could not load submissions.')}finally{setLoading(false)}},[api,base,assignment.id]);
  useEffect(()=>{void load()},[load]);
  const knownIds=Array.from(new Set([...rosterIds,...submissions.map(s=>s.studentId)]));
  const visible=focusStudentId&&!showAll?submissions.filter(s=>s.studentId===focusStudentId):submissions;
  return <Modal title={assignment.title} kicker="Review submissions" onClose={close}>{loading?<Loading/>:<>{error&&<ErrorBox error={error} retry={()=>void load()}/>}<p className="small-muted" style={{marginBottom:14}}>{submissions.length} {submissions.length===1?'submission':'submissions'} · {assignment.points} points possible</p>{focusStudentId&&!showAll&&<Button variant="small" onClick={()=>setShowAll(true)} testId="button-review-all">View all submissions</Button>}{!visible.length&&!error&&<Empty label={focusStudentId&&!showAll?'No response from this student yet':'No responses yet'} hint={focusStudentId&&!showAll?'There is no submission to grade for this student.':'Students’ responses and private files will appear here when they turn in their work.'}/>}<div className="stack">{visible.map(s=><form className="card fields" key={s.id} onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);setSaving(s.id);setError('');try{await api(`${base}/assignments/${encodeURIComponent(assignment.id)}/submissions/${encodeURIComponent(s.id)}`,'PATCH',{score:Number(f.get('score')),feedback:String(f.get('feedback')||'')});await Promise.all([load(),refresh()])}catch(err){setError(err instanceof Error?err.message:'Could not save feedback.')}finally{setSaving(null)}}}><div className="feed-top"><StudentIdentity name={s.studentName} id={s.studentId} knownIds={knownIds}/><span className="small-muted">{dateTime(s.submittedAt)}</span></div><p className="body" style={{whiteSpace:'pre-wrap',overflowWrap:'anywhere'}}>{s.text}</p><SubmissionFile submission={s} base={base} assignmentId={assignment.id}/><label>Score out of {assignment.points}<input name="score" type="number" min="0" max={assignment.points} step="0.01" required defaultValue={s.score??''} data-testid={`input-score-${s.id}`}/></label><label>Feedback<textarea name="feedback" defaultValue={s.feedback||''} placeholder="What worked, and what to try next…" data-testid={`input-feedback-${s.id}`}/></label><div className="form-actions"><Button variant="primary small" type="submit" disabled={saving!==null} testId={`button-save-grade-${s.id}`}><Check/> {saving===s.id?'Saving…':'Save feedback'}</Button></div></form>)}</div></>}</Modal>;
}
function App(){
  const {userId,sessionId}=useAuth();
  // Reset all classroom state in the identity-change render, not a later effect.
  return <Router base="/instructor"><Switch><Route path="/sign-in"><AuthPage/></Route><Route path="/sign-up"><AuthPage/></Route><Route><Workspace key={JSON.stringify([userId,sessionId])}/></Route></Switch></Router>;
}
export default App;